@dataclass
class D:
 x:object
print(asdict(D([1,2])))

from dataclasses import dataclass,field,asdict,astuple,fields,replace
@dataclass
class D:
 x:object
print(astuple(D([1,2])))

from dataclasses import dataclass,field,asdict,astuple,fields,replace
