class D:
 x:object
s={1};r=asdict(D(s));print(r['x'] is s,r['x']==s)

from dataclasses import dataclass,field,asdict,astuple,fields,replace
@dataclass
class D:
 x:object
class Leaf:
 def __deepcopy__(self,memo):
  print('copied')
  return Leaf()
s=Leaf();print(asdict(D(s))['x'] is s)

from dataclasses import dataclass,field,asdict,astuple,fields,replace
@dataclass
class D:
 x:object
print(asdict(D({'a':1}),dict_factory=list))

from dataclasses import dataclass,field,asdict,astuple,fields,replace
@dataclass
class D:
 x:object
r=asdict(D(1),dict_factory=lambda pairs:7)
print(r+1)

from dataclasses import dataclass,field,fields
m={'a':1}
@dataclass
class D:
 x:int=field(default=1,metadata=m)
m['a']=2
print(fields(D)[0].metadata['a'])
try:fields(D)[0].metadata['b']=3
except TypeError:print('readonly')
else:print('mutable')

from dataclasses import dataclass,fields
@dataclass
class A:
 x:int=1
@dataclass
class B(A):
 y:int=2
print(fields(A)[0] is fields(B)[0])

from dataclasses import dataclass,field,asdict,astuple,fields,replace
@dataclass
class D:
 x:object
del D.__dataclass_fields__['x']
try:print(len(fields(D)),asdict(D(1)))
except Exception as e:print(type(e).__name__)

from dataclasses import dataclass,asdict,astuple,replace
@dataclass
class D:
 x:int=7
d=D();del d.x
print(asdict(d),astuple(d),replace(d).x,repr(d))

