from dataclasses import dataclass
@dataclass(frozen=True)
class A:
 x:int
class B(A):pass
b=B(1)
try:b.y=2;print(b.y)
except Exception as e:print(type(e).__name__)

from dataclasses import dataclass,field,fields
@dataclass
class D:
 x:int=field(default_factory=None)
print(fields(D)[0].default_factory is None)

from dataclasses import dataclass,is_dataclass,fields
@dataclass
class A:
 x:int
class B(A):pass
b=B(1)
print(is_dataclass(B),is_dataclass(b))
try:print([f.name for f in fields(B)])
except TypeError:print('TypeError')

from dataclasses import dataclass
