class A:
 x:int
class B(A):pass
print(B(1))

from dataclasses import dataclass,field,fields
@dataclass
class D:x:int=field(default=1,repr=0,compare=None,kw_only=None)
f=fields(D)[0]
print(f.repr == 0,f.compare is None,f.kw_only is None,D())

from dataclasses import field,dataclass
f=field(default_factory=1)
print(f.default_factory)
@dataclass
class D:x:int=f
try:D()
except TypeError:print('TypeError')

from dataclasses import dataclass
@dataclass(frozen=True)
class A:x:int
class B(A):pass
b=B(1);b.y=2;del b.y
print(hasattr(b,'y'))
try:b.x=2
except AttributeError:print('frozen-set')
try:del b.x
except AttributeError:print('frozen-del')

from dataclasses import dataclass,asdict
